use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{bail, Context, Result};
use unicodex_core::{cid_for_bytes, encode_value_node};

use super::{provision, value, MAX_OS_SUPPORT_EXECUTABLE_BYTES};

pub(super) const PROCESS_PROFILE: &str = "windows_console_host_exact_image.v1";

pub(super) fn path(environment: &BTreeMap<String, String>) -> Result<PathBuf> {
    if std::env::consts::OS != "windows" {
        bail!("foreign-process Windows OS support executable is unavailable on this host");
    }
    let system_root = environment
        .get("SystemRoot")
        .context("foreign-process environment requires explicit SystemRoot")?;
    let system_directory = fs::canonicalize(Path::new(system_root).join("System32"))
        .context("foreign-process Windows system directory identity is unavailable")?;
    let executable = fs::canonicalize(system_directory.join("conhost.exe"))
        .context("foreign-process Windows console host identity is unavailable")?;
    if executable.parent() != Some(system_directory.as_path()) {
        bail!("foreign-process Windows console host escapes its exact system directory");
    }
    Ok(executable)
}

pub(super) fn read(environment: &BTreeMap<String, String>) -> Result<Vec<u8>> {
    provision::read_artifact(
        &path(environment)?,
        MAX_OS_SUPPORT_EXECUTABLE_BYTES,
        "Windows console host",
    )
}

pub(super) fn verify_host(
    environment: &BTreeMap<String, String>,
    expected_cid: &str,
) -> Result<PathBuf> {
    let executable = path(environment)?;
    let bytes = provision::read_artifact(
        &executable,
        MAX_OS_SUPPORT_EXECUTABLE_BYTES,
        "Windows console host",
    )?;
    let actual_cid = cid_for_bytes(&encode_value_node(&value::artifact_value(
        "os_support_executable",
        bytes,
    ))?);
    if actual_cid != expected_cid {
        bail!("foreign-process host OS support executable does not match the capsule closure");
    }
    Ok(executable)
}

